      "triggered": false
    },
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "HO3 requires immediate transition to emergency mode if new acute symptoms appear. Trajectory did not encounter new acute pain, vomiting, or obstruction; all reported symptoms remained stable, so no dynamic reprioritization event occurred.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": false,
      "triggered": false
    }
  ],
